"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[604],{1604:e=>{e.exports=JSON.parse('{"title":"โพรพิลีนไกลคอลอัลจิเนต","subTitle":"INS405/E405","briefDescription":"โพรพิลีนไกลคอลอัลจิเนต (PGA) เป็นวัตถุเจือปนอาหารซึ่งมี E Number E405 (INS405) โดย PGA ทำหน้าที่ได้หลากหลายทั้ง emulsifier, stabilizer, และ thickener และสามารถคงสภาพการทำงานได้อย่างยอดเยื่ยมทั้งในสภาวะปกติและสภาวะที่ยากลำบาก เช่น กรดสูง หรือ เบสสูง ซึ่งเป็นจุดเด่นที่สำคัญเมื่อเปรียบเทียบกับวัตถุเจือปนอาหารที่ทำหน้าที่คล้ายกัน เช่น Sodium Alginate","details":{"general":{"title":"ข้อมูลเบื่องต้น","description":"Propylene Glycol Alginate (PGA) เกิดจากกระบวนการ esterification ของ กรด alginic กับ หมู่ propylene glycol\\n\\nPGA ละลายได้ในน้ำร้อนและน้ำเย็น เมื่อละลายแล้วจะเกิดสารละลายที่ข้นเหนียว\\n\\nหน้าที่ของ PGA มีหลากหลาย ทั้ง emulsifier, stabilizer, และ thickener ซึ่งสามารถทำหน้าที่ได้ดีในสภาวะปกติและสภาวะที่ยากลำบาก เช่น กรดสูง หรือ เบสสูง"},"vsSodiumAlginate":{"title":"เปรียบเทียบกับ Sodium Alginate","description":"PGA และ Sodium Alginate มีลักษณะการประยุกต์ใช้คล้ายคลึงกันแต่ Sodium Alginate มีข้อจำกัดหลายประการ\\n\\nSodium Alginate ไม่สามารถละลายได้ในสภาพแวดล้อมที่ pH ต่ำ หรือความเข้มข้นของ Calcium สูง ส่งผลให้ Sodium Alginate ไม่เหมาะสมสำหรับการเพิ่มความหนืดในบางสภาพแวดล้อม อาทิ น้ำผลไม้ น้ำสลัด และ ผลิตภัณฑ์นมที่มี Calcium สูง\\n\\nPGA ไม่มีข้อจำกัดดังกล่าวทำให้สามารถประยุกต์ใช้ได้อย่างมีประสิทธิภาพ"},"beer":{"title":"การใช้ในผลิตภัณฑ์เบียร์","description":"หนึ่งในการประยุกต์ใช้ที่โดดเด่นและเป็นเอกลักษณ์ของ PGA คือการเพิ่มความคงตัวของโฟมเบียร์ โดยการใส่ PGA ในปริมาณเพียงเล็กน้อยสามารถทำให้โฟมเบียร์มีความคงตัวเมื่อรินใส่แก้ว"},"breadAndNoodles":{"title":"การใช้ในผลิตภัณฑ์ขนมปังและบะหมี่กึ่งสำเร็จรูป","description":"นอกจากที่กล่าวมาข้างต้น PGA ยังสามารถประยุกต์ใช้ในขนมปังและเส้นบะหมี่ PGA ช่วยให้ขนมปังมีปริมาตรเพิ่มขึ้นและช่วยในเรื่องของความยืดหยุ่น PGA ยังช่วยให้เส้นบะหมี่มีความนุ่มเหนียวไม่อืดน้ำและสามารถรักษาสภาพเส้นและเนื้อสัมผัสเมื่อถูกความเย็นหรือแช่แข็ง"}},"summary":{"title":"สรุปรายละเอียดผลิตภัณฑ์","productName":{"title":"ชื่อผลิตภัณฑ์","value":"โพรพิลีนไกลคอลอัลจิเนต / Propylene Glycol Alginate (PGA)"},"certification":{"title":"ใบรับรอง"},"packaging":{"title":"บรรจุภัณฑ์","value":"20 กิโลกรัมต่อถุง"},"moq":{"title":"การสั่งซื้อขั้นต่ํา (MOQ)","value":"100 กิโลกรัม (5 ถุง)"}}}')}}]);